import{_ as n,a8 as p,o as s,c as u,ah as i,f6 as d,f7 as c,f8 as _,f9 as m,a as y,a3 as t,K as o,L as b,fa as g,fb as h}from"./chunks/framework.BUAh2RRO.js";import"./chunks/theme.-p-ond56.js";const v=JSON.parse('{"title":"Jupyter 使用问题","description":"","frontmatter":{"title":"Jupyter 使用问题","abstract":"Jupyter Notebook 使用中的常见问题处理，涵盖更换主题背景颜色等个性化配置方法。","created":"2026-05-22T00:00:00.000Z","tags":["Jupyter","Notebook","问题排查"],"type":"故障排查","related":["[[5.IDE与环境-MOC]]","[[Jupyter 保存路径]]","[[Anaconda 环境管理]]"],"reference":null,"category":["🛠️ 工程工具","IDE与环境"]},"headers":[],"relativePath":"vault/Knowledge/Engineering/Jupyter 使用问题.md","filePath":"vault/Knowledge/Engineering/Jupyter 使用问题.md","lastUpdated":1793186727000}'),f={name:"vault/Knowledge/Engineering/Jupyter 使用问题.md"};function k(N,e,j,T,w,x){const r=p("VPNolebaseInlineLinkPreview"),a=p("NolebaseGitContributors"),l=p("NolebaseGitChangelog");return s(),u("div",null,[e[3]||(e[3]=i('<h2 id="jupyter-notebook中的问题" tabindex="-1">jupyter+notebook中的问题 <a class="header-anchor" href="#jupyter-notebook中的问题" aria-label="Permalink to “jupyter+notebook中的问题”">​</a></h2><h2 id="_1、改变主题背景颜色" tabindex="-1">1、改变主题背景颜色 <a class="header-anchor" href="#_1、改变主题背景颜色" aria-label="Permalink to “1、改变主题背景颜色”">​</a></h2><p>安装jupter notebook的自定义主题</p><p><code>pip install --upgrade jupyterthemes</code></p><p>上面一步执行完后继续输入下面代码，可以看到安装的这几个自定义主题的名称</p><p><code>jt -l</code></p><p>如图所示：</p><p><img src="'+d+'"></p><p>现在可以选择一个主题名执行以下代码换皮肤了,例如：</p><p><code>jt -t chesterish -T -N</code></p><p>这就表示选择了chesterish这个主题，-T表示打开顶部的工具栏，-N显示笔记本的名字，当然不想要这两个的话可以吧-T -N删掉</p><p>若要恢复原默认主题，则输入代码：<code>jt -r</code></p><ul><li>这样就可以改变自己的主题背景了，主要是改变颜色！</li></ul><p>下面几个比较不错的主题界面（本人感觉 chesterish 最好）</p><ul><li>oceans16</li></ul><p><img src="'+c+'"></p><ul><li>grade3</li></ul><p><img src="'+_+'"></p><ul><li>onedork</li></ul><p><img src="'+m+'"></p><p>出现问题</p><p>ERROR: Cannot unpack file C:\\Users\\star\\AppData\\Local\\Temp\\pip-unpack-qqnswmhk\\simple.html (downloaded from C:\\Users\\star\\AppData\\Local\\Temp\\pip-req-build-e28mai9a, content-type: text/html); cannot detect archive format</p><p>ERROR: Cannot determine archive format of C:\\Users\\star\\AppData\\Local\\Temp\\pip-req-build-e28mai9a</p><p>输入</p>',24)),y("p",null,[e[1]||(e[1]=t("pip install -i ",-1)),o(r,{href:"https://pypi.tuna.tsinghua.edu.cn/simple",target:"_blank",rel:"noreferrer"},{default:b(()=>[...e[0]||(e[0]=[t("https://pypi.tuna.tsinghua.edu.cn/simple",-1)])]),_:1}),e[2]||(e[2]=t(" --trusted-host pypi.tuna.tsinghua.edu.cn --upgrade jupyterthemes",-1))]),e[4]||(e[4]=i('<h2 id="_2、更改文件存放位置" tabindex="-1">2、更改文件存放位置 <a class="header-anchor" href="#_2、更改文件存放位置" aria-label="Permalink to “2、更改文件存放位置”">​</a></h2><p>⑴ 创建文件夹/目录</p><ul><li>Windows用户在想要存放Jupyter Notebook文件的磁盘中新建文件夹并为该文件夹命名；双击进入该文件夹，然后复制地址栏中的路径。</li><li>Linux/macOS用户在想要存放Jupyter Notebook文件的位置创建目录并为目录命名，命令为：</li></ul><p>mkdir ；进入目录，命令为：</p><p>cd ；查看目录的路径，命令为：</p><p>pwd；复制该路径。</p><ul><li>注意：“”是自定义的目录名。目录名两边不加尖括号“&lt;&gt;”。</li></ul><p>⑵ 配置文件路径</p><ul><li>一个便捷获取配置文件所在路径的命令：</li></ul><p>jupyter notebook --generate-config</p><ul><li><p>注意： 这条命令虽然可以用于查看配置文件所在的路径，但主要用途是是否将这个路径下的配置文件替换为默认配置文件。 如果你是第一次查询，那么或许不会出现下图的提示；若文件已经存在或被修改，使用这个命令之后会出现询问“Overwrite /Users/raxxie/.jupyter/jupyter_notebook_config.py with default config? [y/N]”，即“用默认配置文件覆盖此路径下的文件吗？”，如果按“y”，则完成覆盖，那么之前所做的修改都将失效；如果只是为了查询路径，那么一定要输入“N”。</p><ul><li>配置文件所在路径</li></ul><p><img src="'+g+'"></p></li></ul><p>常规的情况下，Windows和Linux/macOS的配置文件所在路径和配置文件名如下所述：</p><ul><li>Windows系统的配置文件路径：C:\\Users\\.jupyter\\</li><li>Linux/macOS系统的配置文件路径：/Users//.jupyter/ 或 ~/.jupyter/</li><li>配置文件名：jupyter_notebook_config.py</li></ul><p>注意：</p><p>① “”为你的用户名。用户名两边不加尖括号“&lt;&gt;”。</p><p>② Windows和Linux/macOS系统的配置文件存放路径其实是相同的，只是系统不同，表现形式有所不同而已。</p><p>③ Windows和Linux/macOS系统的配置文件也是相同的。文件名以“.py”结尾，是Python的可执行文件。</p><p>④ 如果你不是通过一步到位的方式前往配置文件所在位置，而是一层一层进入文件夹/目录的，那么当你进入家目录后，用ls命令会发现找不到“.jupyter”文件夹/目录。这是因为凡是以“.”开头的目录都是隐藏文件，你可以通过ls -a命令查看当前位置下所有的隐藏文件。</p><p>⑶ 修改配置文件</p><ul><li>Windows系统的用户可以使用文档编辑工具或IDE打开“jupyter_notebook_config.py”文件并进行编辑。常用的文档编辑工具和IDE有记事本、Notepad++、vim、Sublime</li></ul><p>Text、PyCharm等。其中，vim是没有图形界面的，是一款学习曲线较为陡峭的编辑器，其他工具在此不做使用说明，因为上手相对简单。通过vim修改配置文件的方法请继续往下阅读。</p><ul><li>Linux/macOS系统的用户建议直接通过终端调用vim来对配置文件进行修改。具体操作步骤如下：</li></ul><p>⒜ 打开配置文件</p><p>打开终端，输入命令：</p><p>vim ~/.jupyter/jupyter_notebook_config.py</p><p>命令详解</p><p><img src="'+h+'"></p><p>执行上述命令后便进入到配置文件当中了。</p><p>⒝ 查找关键词</p><p>进入配置文件后查找关键词“c.NotebookApp.notebook_dir”。查找方法如下：</p><p>进入配置文件后不要按其他键，用英文半角直接输入/c.NotebookApp.notebook_dir，这时搜索的关键词已在文档中高亮显示了，按回车，光标从底部切换到文档正文中被查找关键词的首字母。</p><p>⒞ 编辑配置文件</p><p>按小写i进入编辑模式，底部出现“--INSERT--”说明成功进入编辑模式。使用方向键把光标定位在第二个单引号上（光标定位在哪个字符，就在这个字符前开始输入），把“⑴ 创建文件夹/目录”步骤中复制的路径粘贴在此处。</p><p>⒟ 取消注释</p><p>把该行行首的井号（#）删除。因为配置文件是Python的可执行文件，在Python中，井号（#）表示注释，即在编译过程中不会执行该行命令，所以为了使修改生效，需要删除井号（#）。</p><p>⒠ 保存配置文件</p><p>先按esc键，从编辑模式退出，回到命令模式。</p><p>再用英文半角直接输入:wq，回车即成功保存且退出了配置文件。</p><p>注意：</p><ul><li>冒号（:） 一定要有，且也是英文半角。</li><li>w：保存。</li><li>q：退出。</li></ul><p>⒡ 验证</p><p>在终端中输入命令jupyter notebook打开Jupyter Notebook</p>',42)),o(a),o(l)])}const S=n(f,[["render",k]]);export{v as __pageData,S as default};
